INSERT INTO public.modules (id, track_id, module_number, title_vi, title_en, description_vi, difficulty, estimated_minutes, order_index) VALUES
  ('D01', 'designer', 'D01', 'Giao Diện Vector, Các Persona & Thiết Lập Bản Vẽ (Artboard)', 'Giao Diện Vector, Các Persona & Thiết Lập Bản Vẽ (Artboard)', 'Nắm vững kiến trúc engine kép độc đáo của Affinity Designer: chuyển đổi linh hoạt giữa Vector Persona, Pixel Persona và Export Persona. Thực hành tổ chức artboard chuyên nghiệp cho giao diện đa thiết bị và ấn phẩm in ấn, kết hợp chế độ xem trước điểm ảnh và lưới căn gióng thông minh.', 'Beginner', 75, 1),
  ('D02', 'designer', 'D02', 'Điểm Node Vector, Đường Vẽ & Hình Học Công Cụ Pen', 'Điểm Node Vector, Đường Vẽ & Hình Học Công Cụ Pen', 'Làm chủ các cơ chế tạo và hiệu chỉnh đường cong Bézier, phân loại node (Sharp, Smooth, Smart) và thao tác tiếp tuyến chuẩn xác.', 'Beginner', 80, 2),
  ('D03', 'designer', 'D03', 'Tạo Hình Nâng Cao & Thao Tác Hình Học Boolean', 'Tạo Hình Nâng Cao & Thao Tác Hình Học Boolean', 'Thực hành các công cụ tạo hình thông minh, Corner Tool và bộ phép toán Boolean (Add, Subtract, Intersect, Xor, Divide) phi phá hủy.', 'Beginner', 85, 3),
  ('D04', 'designer', 'D04', 'Tô Màu, Dải Chuyển Màu, Đường Viền & Biểu Đồ Lực Nhấn', 'Tô Màu, Dải Chuyển Màu, Đường Viền & Biểu Đồ Lực Nhấn', 'Kiểm soát màu sắc, dải màu gradient đa điểm, tùy biến nét vẽ và áp dụng biểu đồ lực nhấn (pressure profile) cho nét vẽ vector.', 'Intermediate', 90, 4),
  ('D05', 'designer', 'D05', 'Quản Lý Layer, Mặt Nạ Vector & Đường Cắt Bố Cục (Clipping)', 'Quản Lý Layer, Mặt Nạ Vector & Đường Cắt Bố Cục (Clipping)', 'Thấu hiểu cấu trúc phân tầng (scene graph), mặt nạ vector, nhóm lớp và các kỹ thuật lồng ghép hình ảnh phi phá hủy.', 'Intermediate', 90, 5),
  ('D06', 'designer', 'D06', 'Nghệ Thuật Chữ (Typography), Chữ Uốn Cong & Phân Cấp Thị Giác', 'Nghệ Thuật Chữ (Typography), Chữ Uốn Cong & Phân Cấp Thị Giác', 'Sử dụng khung chữ nghệ thuật và chữ đoạn văn, gắn chữ chạy theo đường cong Bézier, tinh chỉnh tracking/kerning và xây dựng kiểu mẫu chữ (text styles).', 'Intermediate', 90, 6),
  ('D07', 'designer', 'D07', 'Hệ Lưới Isometric, Phối Cảnh Trục Đo & Mặt Phẳng 3D', 'Hệ Lưới Isometric, Phối Cảnh Trục Đo & Mặt Phẳng 3D', 'Thiết lập hệ lưới Isometric đa góc nhìn, căn gióng mặt phẳng chiếu và dựng đối tượng không gian ba chiều chuẩn kỹ thuật.', 'Intermediate', 90, 7),
  ('D08', 'designer', 'D08', 'Biểu Tượng Tái Sử Dụng (Symbols), Tài Nguyên Liên Kết & Thư Viện Asset', 'Biểu Tượng Tái Sử Dụng (Symbols), Tài Nguyên Liên Kết & Thư Viện Asset', 'Xây dựng hệ thống component tái sử dụng, đồng bộ hóa thay đổi trên toàn thiết kế và quản lý danh mục tài nguyên thông minh.', 'Advanced', 90, 8),
  ('D09', 'designer', 'D09', 'Tích Hợp Pixel Persona, Đổ Bóng & Kết Cấu Hạt (Texture)', 'Tích Hợp Pixel Persona, Đổ Bóng & Kết Cấu Hạt (Texture)', 'Kết hợp sức mạnh điểm ảnh vào thiết kế vector: sử dụng cọ vẽ raster, tạo hạt noise, tạo khối và bóng đổ tự nhiên.', 'Advanced', 90, 9),
  ('D10', 'designer', 'D10', 'Xuất Bản Dự Án Thực Chiến, Cắt Lát (Slices) & Đóng Gói Sản Phẩm', 'Xuất Bản Dự Án Thực Chiến, Cắt Lát (Slices) & Đóng Gói Sản Phẩm', 'Sử dụng Export Persona để tạo các vùng cắt lát đa kích thước (@1x, @2x, @3x), xuất định dạng SVG/PDF/PNG và bàn giao file gốc chuẩn sản xuất.', 'Advanced', 90, 10),
  ('P01', 'photo', 'P01', 'Giao Diện Photo, Thanh Điều Khiển & Các Bảng Studio', 'Giao Diện Photo, Thanh Điều Khiển & Các Bảng Studio', 'Khám phá không gian làm việc chuyên nghiệp trong Pixel Studio / Affinity Photo: điều hướng bảng Studio, quy trình màu HDR 32-bit dấu phẩy động, phục hồi phơi sáng và cân bằng trắng trong Develop Studio, khử quang sai và hình học vùng vẽ phi phá hủy.', 'Beginner', 80, 1),
  ('P02', 'photo', 'P02', 'Công Cụ Vùng Chọn & Nguyên Lý Tách Nền Chuẩn Xác', 'Công Cụ Vùng Chọn & Nguyên Lý Tách Nền Chuẩn Xác', 'Làm chủ các công cụ chọn điểm ảnh trong Pixel Studio / Affinity Photo: Selection Brush với bắt dính biên, các chế độ Freehand Lasso và đa giác, tính toán biên tóc phức tạp qua Refine Selection và kiến trúc mặt nạ pixel phi phá hủy.', 'Beginner', 85, 2),
  ('P03', 'photo', 'P03', 'Hệ Thống Layer Nâng Cao, Masking & Chỉnh Sửa Phi Phá Hủy', 'Hệ Thống Layer Nâng Cao, Masking & Chỉnh Sửa Phi Phá Hủy', 'Nắm vững kiến trúc layer phi phá hủy trong Pixel Studio / Affinity Photo: phân biệt Pixel Layer và Image Layer, lồng lớp con (Clipping), Adjustment Layers (Curves, Levels, HSL, B&W), Live Filters và toán học của Multiply, Screen, Overlay, Color Dodge.', 'Beginner', 85, 3),
  ('P04', 'photo', 'P04', 'Chấm Sửa Chân Dung, Phục Chế Chi Tiết & Inpainting', 'Chấm Sửa Chân Dung, Phục Chế Chi Tiết & Inpainting', 'Thực hành các công cụ phục chế và retouch chuyên nghiệp trong Pixel Studio / Affinity Photo: xóa đối tượng phi phá hủy với Inpainting Brush, căn nguồn mẫu Clone Stamp và Healing Brush, vá kết cấu Patch Tool và quy trình Frequency Separation tách hạt khỏi sắc độ.', 'Intermediate', 90, 4),
  ('P05', 'photo', 'P05', 'Cân Chỉnh Màu Sắc, Đường Cong Curves & Hiệu Ứng Sắc Độ', 'Cân Chỉnh Màu Sắc, Đường Cong Curves & Hiệu Ứng Sắc Độ', 'Kiểm soát ánh sáng và màu sắc chuyên sâu trong Pixel Studio / Affinity Photo: đọc biểu đồ Histogram theo từng kênh, cân bằng trắng theo điểm xám trung tính 18%, chỉnh đường cong RGB Curves chữ S, chọn dải màu HSL, Gradient Map và nạp hồ sơ 3D LUT (.cube).', 'Intermediate', 90, 5),
  ('P06', 'photo', 'P06', 'Bộ Lọc Động Trực Tiếp (Live Filters) & Hiệu Ứng Layer', 'Bộ Lọc Động Trực Tiếp (Live Filters) & Hiệu Ứng Layer', 'Áp dụng các bộ lọc quang học chuyên nghiệp trong Pixel Studio / Affinity Photo: quy trình Live Filter phi phá hủy, làm nét với High Pass, Clarity và Unsharp Mask, khử nhiễu hai kênh Luminance/Chrominance và bộ lọc Live Lighting kèm bản đồ nổi Bump Map 3D.', 'Intermediate', 85, 6),
  ('P07', 'photo', 'P07', 'Ghép Ảnh Nghệ Thuật (Compositing) & Hòa Trộn Ánh Sáng', 'Ghép Ảnh Nghệ Thuật (Compositing) & Hòa Trộn Ánh Sáng', 'Kỹ thuật ghép ảnh nâng cao trong Pixel Studio / Affinity Photo: khớp phối cảnh, Live Perspective và Warp Groups, căn chỉnh đường chân trời, hiệu ứng Light Wrap, bóng đổ hai tầng và đồng bộ ánh sáng không gian.', 'Advanced', 90, 7),
  ('P08', 'photo', 'P08', 'Tích Hợp Kiểu Chữ Đồ Họa & Đồ Họa Vector Vào Ảnh', 'Tích Hợp Kiểu Chữ Đồ Họa & Đồ Họa Vector Vào Ảnh', 'Bố cục chữ nghệ thuật và đồ họa trong Pixel Studio / Affinity Photo: phân biệt Artistic Text và Frame Text, hiệu ứng Quick FX / Layer Effects (Bevel/Emboss, Shadows, Glows), tích hợp hình khối vector và kỹ thuật đặt chữ sau chủ thể.', 'Intermediate', 80, 8),
  ('P09', 'photo', 'P09', 'Quy Trình Phát Triển Ảnh RAW & Không Gian Màu 32-Bit', 'Quy Trình Phát Triển Ảnh RAW & Không Gian Màu 32-Bit', 'Làm việc trong phòng tối kỹ thuật số chuyên nghiệp của Affinity (Develop Studio & Pixel Studio): giải mã cảm biến 32-bit float, phát triển RAW phi phá hủy (RAW Layer Linked/Embedded), khử méo ống kính và quang sai màu, cùng xử lý hàng loạt với Macro.', 'Advanced', 90, 9),
  ('P10', 'photo', 'P10', 'Đồ Án Tốt Nghiệp Capstone — Quy Trình Xử Lý Ảnh Thương Mại', 'Đồ Án Tốt Nghiệp Capstone — Quy Trình Xử Lý Ảnh Thương Mại', 'Thực hiện quy trình bàn giao chuyên nghiệp trong Pixel Studio / Export Persona: cắt lát xuất đa kênh (1x, 2x, 3x, WebP, SVG, AVIF, TIFF, PDF), quản lý không gian màu và Rendering Intents (sRGB, Display P3, Adobe RGB 1998, ProPhoto RGB), tối ưu nén tệp và hoàn thành đồ án Capstone Track 2.', 'Advanced', 95, 10),
  ('B01', 'publisher', 'B01', 'Thiết Lập Trang Đôi Tạp Chí, Lề Tràn 3mm & Hệ Thống Lưới', 'Thiết Lập Trang Đôi Tạp Chí, Lề Tràn 3mm & Hệ Thống Lưới', 'Làm chủ cấu trúc dàn trang trong Layout Studio (không gian dàn trang Publisher): tính toán trang đối diện (Facing Pages) hay trang đơn, lề gáy đóng sách (Gutter), lề tràn xén Bleed 3mm, hệ thống trang mẫu Master Pages kế thừa cha-con, đánh số trang tự động, lưới đường cơ sở Baseline Grid và nối luồng khung văn bản nhiều cột.', 'Beginner', 80, 1),
  ('S01', 'scripting', 'S01', 'Khởi Động Lập Trình V8 JavaScript DOM & Kết Nối Máy Chủ MCP', 'Khởi Động Lập Trình V8 JavaScript DOM & Kết Nối Máy Chủ MCP', 'Tìm hiểu kiến trúc điều khiển phần mềm bằng mã lệnh trong Serif Affinity 3.0: bộ thực thi Google V8 nhúng trực tiếp, ranh giới bảo mật Sandbox của hệ thống tệp, cơ chế nạp module gốc (/application.js, /document.js), kết nối cầu nối MCP qua giao thức SSE trên cổng 6767 và viết các script tự động hóa đầu tiên để trích xuất thông số tài liệu và Session UUID.', 'Beginner', 75, 1)
