-- Catalog IDs derived from the approved curriculum (TASK-030 / REQ-BE-001).
ON CONFLICT (id) DO UPDATE SET track_id = EXCLUDED.track_id, title_vi = EXCLUDED.title_vi,
  module_number = EXCLUDED.module_number, description_vi = EXCLUDED.description_vi,
  difficulty = EXCLUDED.difficulty, estimated_minutes = EXCLUDED.estimated_minutes, order_index = EXCLUDED.order_index;

ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, track_id = EXCLUDED.track_id,
  title_vi = EXCLUDED.title_vi, order_index = EXCLUDED.order_index,
  duration_minutes = EXCLUDED.duration_minutes, difficulty = EXCLUDED.difficulty;
